"Seedance 2.5(最新,单段30秒直出,参考上限30图+10视频+10音频,480p/720p)": "Seedance 2.5 (mới nhất, video 30 giây trong một lần tạo, tối đa 30 ảnh + 10 video + 10 audio tham chiếu, 480p/720p)",
"Seedance 2.0(音画同生,多模态生视频,最高4K)": "Seedance 2.0 (âm thanh và hình ảnh đồng thời, tạo video đa phương thức, tối đa 4K)",
"对话记忆": "Bộ nhớ hội thoại",
"对话记忆额度(KB,默认 16):创作型 Agent 每次运行接续上次会话,多轮对话有连续记忆;单个会话历史超过该额度自动新开会话防膨胀(扇出型无状态 Agent 本就每单全新会话,不受此项影响)。调大可保留更长的连续记忆,但 resume 每轮重发全部历史,越大越慢、token 消耗越高。拖到 0 即完全关闭:所有 Agent(含总制片)每次运行/发言都是全新会话,跨工单信息只靠落盘产物(bible、工单档案等)传递,可显著省 token,但对话上下文不再延续。全局设置,保存后立即对后续运行生效;调小或关闭期间会话号照常回存,重新调大后从最近一次会话继续。": "Hạn mức bộ nhớ hội thoại (KB, mặc định 16): Agent sáng tạo tiếp nối phiên trước ở mỗi lần chạy nên hội thoại nhiều lượt có trí nhớ liên tục; khi lịch sử một phiên vượt hạn mức này, phiên mới sẽ tự mở để chống phình to (Agent fan-out không trạng thái vốn mỗi phiếu một phiên mới nên không bị ảnh hưởng). Tăng hạn mức giữ được trí nhớ liên tục dài hơn, nhưng resume gửi lại toàn bộ lịch sử mỗi lượt — càng lớn càng chậm và càng tốn token. Kéo về 0 để tắt hoàn toàn: mọi Agent — kể cả Tổng chế tác — đều bắt đầu phiên mới ở mỗi lần chạy/phát ngôn, thông tin giữa các phiếu chỉ truyền qua sản phẩm đã lưu trên đĩa (bible, hồ sơ phiếu…), tiết kiệm token đáng kể nhưng mất tính liên tục của hội thoại. Cài đặt toàn cục, lưu xong áp dụng ngay cho các lần chạy sau; trong lúc giảm hoặc tắt, ID phiên vẫn được lưu như thường, tăng lại sẽ tiếp tục từ phiên gần nhất.",
"✓ 会话恢复生效中:单会话超过 {kb} KB 自动新开": "✓ Khôi phục phiên đang hoạt động: phiên vượt {kb} KB sẽ tự mở phiên mới",
"对话记忆需为 0-{max} 的整数(KB,0=关闭)": "Bộ nhớ hội thoại phải là số nguyên từ 0 đến {max} (KB, 0 = tắt)",
"已关闭:每次运行全新会话": "Đã tắt: mỗi lần chạy là phiên mới",
"每 Agent 并发额度": "Hạn mức song song mỗi Agent",
"扇出型 Agent(场景资产、视频生成、审核、验收评分等按场景/组一单的工位)同一 Agent 可同时运行的工单数上限,默认 5。创作型 Agent 为保护会话连续性恒为串行,不受此值影响;全部运行仍受全局 8 个进程槽总闸。每个并发 = 一个真实的模型 CLI 进程,调大会成倍加快额度消耗,网络代理高并发下也更易断连,建议逐步上调。": "Giới hạn số phiếu mà cùng một Agent dạng fan-out (các vị trí xử lý một phiếu cho mỗi bối cảnh/nhóm như tài sản bối cảnh, tạo video, kiểm duyệt, chấm nghiệm thu) có thể chạy đồng thời; mặc định là 5. Agent sáng tạo luôn chạy tuần tự để bảo vệ tính liên tục của phiên nên không chịu ảnh hưởng; toàn bộ vẫn qua cổng tổng 8 khe tiến trình toàn cục. Mỗi luồng song song = một tiến trình CLI mô hình thật — tăng giá trị sẽ tiêu hao hạn mức nhanh tương ứng và dễ đứt kết nối proxy khi song song cao, nên tăng dần từng bước.",
"运行超时(分钟)": "Thời gian chờ chạy (phút)",
"无输出超时(分钟)": "Thời gian chờ không đầu ra (phút)",
"运行超时:单个工单从启动算起的墙钟上限,默认 120 分钟(总制片要等整条流水线,自动放宽 4 倍),到点连同派生子进程一起终止并记为出错,是回收挂死进程的最后防线。无输出超时:引擎连续多长时间没有任何事件输出即判定挂死并终止,默认 30 分钟,填 0 关闭;比墙钟更早识别 API 长连接不返回、代理断流等假死,又不会误伤跑得慢但在正常干活的长批量任务(总制片大部分时间静默等子任务,不受此项约束)。注意单次工具调用期间引擎不会有事件输出,该值须大于工单里最长的一次工具调用。均为全局设置,保存后对后续启动的工单生效。": "Thời gian chờ chạy: giới hạn thời gian thực của một phiếu tính từ lúc khởi động, mặc định 120 phút (Tổng chế tác phải đợi cả pipeline nên tự động nới 4 lần); khi hết, lần chạy cùng các tiến trình con bị kết thúc và ghi lỗi — tuyến phòng thủ cuối để thu hồi tiến trình treo. Thời gian chờ không đầu ra: engine không phát ra sự kiện nào liên tục quá thời gian này thì coi là treo và kết thúc, mặc định 30 phút, điền 0 để tắt; phát hiện treo (kết nối API dài không trả về, đứt proxy) sớm hơn nhiều so với thời gian thực mà không làm hại các tác vụ hàng loạt chạy chậm nhưng bình thường (Tổng chế tác phần lớn thời gian im lặng đợi tác vụ con nên được miễn). Lưu ý trong một lần gọi công cụ engine không phát sự kiện, nên giá trị này phải lớn hơn lần gọi công cụ dài nhất trong phiếu. Đều là cài đặt toàn cục, có hiệu lực với các phiếu khởi động sau khi lưu.",
"运行超时需为 {min}-{max} 的整数(分钟)": "Thời gian chờ chạy phải là số nguyên từ {min} đến {max} (phút)",
