"(两平台账号与 Key 不互通,「接口区域」须与 Key 来源一致);克隆音色需先在平台创建;Agent 可用 --voice 按角色覆盖(传 voice_id)": " (tài khoản và Key của hai nền tảng không dùng chung; “Khu vực API” phải khớp với nơi tạo Key); giọng nhân bản phải được tạo trên nền tảng trước; Agent có thể ghi đè theo nhân vật bằng --voice (truyền voice_id)",
"MiniMax 图片生成 API(Image-01,文/图生图,参考图仅 1 张);Key 在": "API tạo ảnh MiniMax (Image-01, văn bản/ảnh sang ảnh, chỉ 1 ảnh tham chiếu); Key tại",
"MiniMax 视频生成 API(MiniMax-H3,音画同生,支持首尾帧/多参考图/参考音视频);分辨率仅 768P/2K 两档:「输出设置」的 360p/480p/720p 自动映射 768P,1080p/4k 映射 2K;时长 4-15 整数秒;Key 在": "API tạo video MiniMax (MiniMax-H3, đồng sinh âm thanh-hình ảnh, hỗ trợ khung đầu/cuối, nhiều ảnh tham chiếu, âm thanh/video tham chiếu); chỉ 2 mức phân giải 768P/2K: 360p/480p/720p trong “Cài đặt đầu ra” tự động ánh xạ sang 768P, 1080p/4k sang 2K; thời lượng 4–15 giây nguyên; Key tại",
"MiniMax 音乐生成 API(Music 系列);取消「强制纯音乐」时按 prompt 自动写词演唱;输出仅 .mp3/.wav;Key 在": "API tạo nhạc MiniMax (dòng Music); khi bỏ chọn “bắt buộc nhạc không lời”, lời sẽ được tự viết theo prompt và hát; đầu ra chỉ .mp3/.wav; Key tại",
