"诊断数据:本地记录运行事件与经验卡,手动导出诊断包提交给开发者;永不自动上传": "Dữ liệu chẩn đoán: ghi cục bộ các sự kiện chạy và thẻ kinh nghiệm, xuất gói chẩn đoán thủ công để gửi cho nhà phát triển; không bao giờ tự động tải lên",
"🩺 诊断数据": "🩺 Dữ liệu chẩn đoán",
"本地采集": "Thu thập cục bộ",
"开启时在运行结束与生成结束处按字段白名单记录结构化事件(引擎/Agent/渠道/状态/时长/脱敏后的错误模板),只写入本机 data/.videoagents/telemetry/,不含提示词、项目内容、文件路径与 API Key,永不自动上传。「导出诊断包」生成一个 zip(事件 + 环境摘要 + 下方勾选的经验卡),由你自行提交给开发者(如 GitHub issue 附件),用于改进产品。": "Khi bật, các sự kiện có cấu trúc được ghi lại lúc kết thúc chạy/kết thúc sinh nội dung theo danh sách trắng trường dữ liệu (engine/Agent/kênh/trạng thái/thời lượng/mẫu lỗi đã ẩn danh), chỉ ghi vào data/.videoagents/telemetry/ trên máy này — không chứa prompt, nội dung dự án, đường dẫn tệp hay API Key, và không bao giờ tự động tải lên. \"Xuất gói chẩn đoán\" tạo một tệp zip (sự kiện + tóm tắt môi trường + các thẻ kinh nghiệm được chọn bên dưới) để bạn tự gửi cho nhà phát triển (ví dụ đính kèm GitHub issue) nhằm cải thiện sản phẩm.",
