"点击「启用」后,可在下方管理已入库的素材;人物预览页每张形象图会出现「入库」按钮,分镜重出时已入库(Active)的参考图自动以资产 URI(asset://素材ID)提交。": "Sau khi bấm 「Bật」, quản lý tài sản đã vào kho ở bên dưới; mỗi ảnh trên trang Xem trước nhân vật sẽ có nút 「Vào kho」, khi tạo lại nhóm, ảnh tham chiếu đã vào kho (Active) sẽ tự động gửi bằng URI tài sản (asset://ID).",
"注意:上传入库为异步审核(Processing → Active/Failed),仅 Active 状态的素材可用于视频生成;素材按方舟「项目」隔离,下方 ProjectName 须与「生成模型」页视频生成所用方舟 API Key 所属项目一致(默认 default)。": "Lưu ý: vào kho được kiểm duyệt bất đồng bộ (Processing → Active/Failed); chỉ tài sản Active mới dùng được để tạo video. Tài sản được cách ly theo「dự án」Ark — ProjectName bên dưới phải trùng với dự án của Ark API Key dùng tạo video ở trang「Mô hình tạo」(mặc định default).",
