"经 yt-dlp 按 ≤1080p 下载到项目文件夹,再压缩为小画幅代理用于分析;下载受网络与站点限制(Bilibili 高清可能需要登录 cookie)。": "Tải bằng yt-dlp ở ≤1080p vào thư mục dự án, rồi nén thành proxy độ phân giải thấp để phân tích; phụ thuộc mạng và giới hạn của trang (Bilibili HD có thể cần cookie đăng nhập).",
"🤖 全部 AI 分析": "🤖 Phân tích AI tất cả",
