"镜头分割时,上一个切点后此时长内的切换会被合并;快切素材建议调小。改后点「✂ 重新分割」生效(默认 0.5)": "Khi tách cảnh, các chuyển cảnh trong khoảng thời gian này sau điểm cắt trước sẽ bị gộp; nên giảm với video cắt nhanh. Sửa xong bấm “✂ Tách lại” để áp dụng (mặc định 0.5)",
