"素材库 — Agentics:VideoAgents": "Thư viện tư liệu — Agentics: VideoAgents",
"素材库:上传视频或粘贴 YouTube/Bilibili 链接,自动镜头分割成分镜 clip、语音转文字,并可让默认 CLI 引擎看图写出画面含义;产物为 clip 视频 + 结构化 JSON": "Thư viện tư liệu: tải video lên hoặc dán liên kết YouTube/Bilibili; tự động tách cảnh thành clip, chuyển lời nói thành văn bản, và để engine CLI mặc định mô tả ý nghĩa hình ảnh; đầu ra là video clip + JSON có cấu trúc",
